import {useEffect} from 'react';
import Yagr from '@gravity-ui/yagr';
import type {MinimalValidConfig} from '@gravity-ui/yagr';

type ThemeValue = 'light' | 'dark';

type CpuPoint = {
    timestamp: number;
    value: number;
};

type CpuUsageChartProps = {
    points: CpuPoint[];
    theme: ThemeValue;
};

const DAY_MS = 24 * 60 * 60 * 1000;

function createConfig(theme: ThemeValue, firstPoint: CpuPoint): MinimalValidConfig {
    return {
        timeline: [firstPoint.timestamp],
        series: [
            {
                id: 'cpu',
                name: 'CPU',
                data: [firstPoint.value],
                color: 'var(--g-color-text-brand)',
                scale: 'y',
            },
        ],
        chart: {
            appearance: {theme},
            series: {
                type: 'line',
                width: 1.5,
                interpolation: 'linear',
            },
            size: {
                adaptive: true,
                resizeDebounceMs: 100,
            },
        },
        scales: {
            x: {},
            y: {min: 0, max: 100},
        },
        cursor: {},
        tooltip: {show: true},
    };
}

export function useCpuUsageChart(
    element: HTMLElement | null,
    props: CpuUsageChartProps,
): void {
    useEffect(() => {
        if (!element) {
            return undefined;
        }

        let chart: Yagr | undefined;
        const config = createConfig(props.theme, props.points[0]);
        const timeline: number[] = [props.points[0].timestamp];
        const series = config.series;
        const values: (number | null)[] = [props.points[0].value];
        series[0].data = values;

        try {
            chart = new Yagr(element, config);
        } catch {
            return undefined;
        }

        const appendPoints = (points: CpuPoint[]) => {
            const splice = Math.max(0, timeline.length + points.length - 1);
            const newPoints = points.slice(0, DAY_MS);
            const newTimeline = newPoints.map(({timestamp}) => timestamp);
            const newValues = newPoints.map(({value}) => value);

            timeline.push(...newTimeline);
            values.push(...newValues);
            if (splice > 0) {
                timeline.splice(0, splice);
                values.splice(0, splice);
            }

            chart?.setSeries(timeline, series, {incremental: false});
        };

        if (props.points.length > 1) {
            appendPoints(props.points.slice(1));
        }

        return () => {
            chart?.dispose();
            element.classList.remove('yagr');
        };
    }, [element, props.theme, props.points]);
}
import React from 'react';
import {Box, Flex, Text} from '@gravity-ui/uikit';
import {useThemeValue} from '@gravity-ui/uikit';

import './cpu-usage-chart.css';
import {useCpuUsageChart} from './cpu-usage-chart';

const INITIAL_POINTS = Array.from({length: 43_200}, (_, index) => {
    const timestamp = Date.now() - (43_199 - index) * 2_000;
    return {
        timestamp,
        value: 30 + 25 * Math.sin((index / 43_200) * Math.PI * 4) + Math.random() * 5,
    };
});

export function MonitoringPage() {
    const [points, setPoints] = React.useState(INITIAL_POINTS);
    const [chartElement, setChartElement] = React.useState<HTMLElement | null>(null);
    const themeValue = useThemeValue() === 'dark' ? 'dark' : 'light';

    useCpuUsageChart(chartElement, {points, theme: themeValue});

    React.useEffect(() => {
        const interval = window.setInterval(() => {
            const timestamp = Date.now();
            const lastPoint = points[points.length - 1];
            const value = lastPoint.value + (Math.random() - 0.5) * 6;
            setPoints((currentPoints) => [...currentPoints.slice(1), {timestamp, value}]);
        }, 2_000);

        return () => {
            window.clearInterval(interval);
        };
    }, [points]);

    return (
        <Box spacing={{p: 4}} style={{height: '100%'}}>
            <Flex direction="column" height="100%" gap={2}>
                <Text variant="header-1">Мониторинг</Text>
                <Text variant="body-1">Загрузка CPU за последние сутки</Text>
                <div ref={setChartElement} className="cpu-usage-chart" />
            </Flex>
        </Box>
    );
}
